	/* must be huge page aligned */
	if (desc->pgoff & (~huge_page_mask(h) >> PAGE_SHIFT))
		return -EINVAL;

	vma_len = (loff_t)vma_desc_size(desc);
	len = vma_len + ((loff_t)desc->pgoff << PAGE_SHIFT);
