	if (inode->i_flags & S_PRIVATE)
		vma_flags_set(&vma_flags, VMA_NORESERVE_BIT);

	if (hugetlb_reserve_pages(inode,
			desc->pgoff >> huge_page_order(h),
			len >> huge_page_shift(h), desc,
			vma_flags) < 0)
